# PTX source for cumulative product along dim=1 (row‑wise) on fp16 tensors.
PTX_SOURCE = r'''
.version 7.2
.target sm_80
.address_size 64

.visible .entry cumprod_kernel(
    .param .u64 inp_ptr,
    .param .u64 out_ptr
)
{
    // ------------------------------
    // Register declarations
    // ------------------------------
    .reg .pred   %p<5>;
    .reg .b32    %r<15>;
    .reg .b64    %rd<20>;
    .reg .f16    %f16<2>;
    .reg .f32    %f32<9>;

    // ------------------------------
    // Load kernel parameters
    // ------------------------------
    ld.param.u64    %rd1, [inp_ptr];
    ld.param.u64    %rd2, [out_ptr];

    // ------------------------------
    // Thread / block identification
    // ------------------------------
    mov.u32         %r1, %ctaid.x;        // blockIdx.x   (row index)
    mov.u32         %r2, %ntid.x;        // blockDim.x   (threads per block)
    mov.u32         %r3, %tid.x;         // threadIdx.x  (lane index)

    // ------------------------------
    // Constants (hard‑coded for this model)
    // ------------------------------
    // COLS = 32768, SEGMENT = COLS / BLOCK_DIM = 128
    .const .u32 COLS        32768;
    .const .u32 SEGMENT     128;

    // ------------------------------
    // Compute base address for this row (in bytes)
    // row_offset_bytes = row * COLS * sizeof(half)
    // ------------------------------
    cvt.u64.u32     %rd3, %r1;           // row as 64‑bit
    mov.u64         %rd4, COLS;
    mul.lo.u64      %rd5, %rd3, %rd4;    // row * COLS
    shl.b64         %rd5, %rd5, 1;       // *2 (size of half)

    add.u64         %rd6, %rd1, %rd5;    // input row base pointer
    add.u64         %rd7, %rd2, %rd5;    // output row base pointer

    // ------------------------------
    // Shared memory for per‑thread segment products
    // ------------------------------
    .shared .align 4 .b32 sdata[256];

    // ------------------------------
    // First pass: compute local prefix products and store them unscaled
    // ------------------------------
    // Initialize running product to 1.0 (fp32)
    mov.f32         %f32<0>, 1.0;

    // Loop over elements assigned to this thread (128 iterations)
    mov.u32         %r4, 0;               // i = 0
LOOP_SEG:
    setp.ge.u32     %p1, %r4, SEGMENT;
    @%p1 bra        END_LOOP_SEG;

    // col = threadIdx.x + i * blockDim.x
    mad.lo.u32      %r5, %r4, %r2, %r3;   // r5 = i*blockDim + threadIdx

    // byte offset = col * 2
    cvt.u64.u32     %rd8, %r5;
    shl.b64         %rd8, %rd8, 1;        // *2

    // Load input half
    add.u64         %rd9, %rd6, %rd8;
    ld.global.u16   %r6, [%rd9];
    // Convert to fp32
    cvt.f32.f16     %f32<1>, %r6;

    // Update running product
    mul.f32         %f32<0>, %f32<0>, %f32<1>;

    // Store unscaled prefix result (still fp16)
    cvt.f16.f32     %f16<0>, %f32<0>;
    add.u64         %rd10, %rd7, %rd8;
    st.global.u16   [%rd10], %f16<0>;

    // Increment loop counter
    add.u32         %r4, %r4, 1;
    bra.uni         LOOP_SEG;
END_LOOP_SEG:

    // Store this thread's total segment product into shared memory (fp32 -> u32)
    cvt.u32.f32     %r7, %f32<0>;
    st.shared.u32   [sdata+%r3*4], %r7;

    // ------------------------------
    // Synchronize threads
    // ------------------------------
    bar.sync 0;

    // ------------------------------
    // Exclusive scan of per‑thread segment products (naïve O(N^2) scan)
    // ------------------------------
    // Load own segment product
    ld.shared.u32   %r8, [sdata+%r3*4];
    cvt.f32.u32     %f32<2>, %r8;          // thread_prod

    // Compute product of all previous thread segment products
    mov.f32         %f32<3>, 1.0;          // prefix_before = 1.0
    mov.u32         %r9, 0;               // j = 0
PREFIX_LOOP:
    setp.ge.u32     %p2, %r9, %r3;
    @%p2 bra        END_PREFIX_LOOP;
    ld.shared.u32   %r10, [sdata+%r9*4];
    cvt.f32.u32     %f32<4>, %r10;
    mul.f32         %f32<3>, %f32<3>, %f32<4>;
    add.u32         %r9, %r9, 1;
    bra.uni         PREFIX_LOOP;
END_PREFIX_LOOP:

    // ------------------------------
    // Second pass: scale the previously stored prefixes by prefix_before
    // ------------------------------
    // Re‑loop over the segment
    mov.u32         %r4, 0;               // i = 0
SECOND_LOOP:
    setp.ge.u32     %p3, %r4, SEGMENT;
    @%p3 bra        END_SECOND_LOOP;

    // col = threadIdx.x + i * blockDim.x
    mad.lo.u32      %r5, %r4, %r2, %r3;

    // byte offset = col * 2
    cvt.u64.u32     %rd11, %r5;
    shl.b64         %rd11, %rd11, 1;

    // Load previously stored (unscaled) half result
    add.u64         %rd12, %rd7, %rd11;
    ld.global.u16   %r6, [%rd12];
    cvt.f32.f16     %f32<5>, %r6;

    // Multiply by prefix_before
    mul.f32         %f32<5>, %f32<5>, %f32<3>;

    // Store final fp16 result
    cvt.f16.f32     %f16<1>, %f32<5>;
    st.global.u16   [%rd12], %f16<1>;

    // Increment i
    add.u32         %r4, %r4, 1;
    bra.uni         SECOND_LOOP;
END_SECOND_LOOP:

    ret;
}
'''
