# Python wrapper that loads and launches the PTX kernel
# ----------------------------------------------------------------------
import torch
import torch.nn as nn

# The harness is assumed to provide these two functions
# from ptx_harness import ptx_load, ptx_launch

class ModelNew(nn.Module):
    def __init__(self, dim):
        super().__init__()
        self.dim = dim
        # Load PTX module
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Output tensor
        out = torch.empty_like(x)

        # Kernel launch parameters (one block per row)
        batch = x.shape[0]
        grid  = (batch, 1, 1)
        block = (256, 1, 1)

        # Argument list: input pointer, output pointer
        args = [x.data_ptr(), out.data_ptr()]

        # Launch the PTX kernel
        ptx_launch(self.module, "cumprod_kernel", grid, block, args)

        return out
